import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.BuUvxvtQ.js";const h=JSON.parse('{"title":"Automatic Recommendations","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/automatic-recommendations.md","filePath":"web-app/automatic-recommendations.md"}'),r={name:"web-app/automatic-recommendations.md"};function s(i,e,d,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="automatic-recommendations" tabindex="-1">Automatic Recommendations <a class="header-anchor" href="#automatic-recommendations" aria-label="Permalink to &quot;Automatic Recommendations&quot;">​</a></h1><p>The <strong>Automatic recommendations</strong> page (<code>/automatic-recommendations</code>) schedules an outfit recommendation using a manual location. This is useful for planning ahead — a morning commute, a weekend hike, or an event — and reviewing the result later. Delivery is best-effort, not a guarantee of an exact minute.</p><h2 id="creating-a-schedule" tabindex="-1">Creating a schedule <a class="header-anchor" href="#creating-a-schedule" aria-label="Permalink to &quot;Creating a schedule&quot;">​</a></h2><p>Each schedule includes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>A name for the schedule (e.g. &quot;Morning commute&quot;).</td></tr><tr><td><strong>Latitude &amp; longitude</strong></td><td>A manual location — GPS is not used. Latitude −90 to 90, longitude −180 to 180.</td></tr><tr><td><strong>Run time</strong></td><td>When the recommendation should be generated.</td></tr><tr><td><strong>Recurrence</strong></td><td><code>Once</code>, <code>Daily</code>, or <code>Weekly</code>.</td></tr><tr><td><strong>Unit preference</strong></td><td><code>metric</code> (°C, km/h) or <code>imperial</code> (°F, mph).</td></tr><tr><td><strong>Timezone</strong></td><td>Detected automatically from your browser.</td></tr><tr><td><strong>Styling prompt</strong></td><td>Optional Pro/Dev guidance (max 1000 characters); ignored for Free schedules.</td></tr></tbody></table><h2 id="managing-schedules" tabindex="-1">Managing schedules <a class="header-anchor" href="#managing-schedules" aria-label="Permalink to &quot;Managing schedules&quot;">​</a></h2><ul><li><strong>Pause / resume</strong> any schedule without deleting it.</li><li>Each schedule shows its recurrence and next run time.</li><li>The list updates immediately after changes.</li></ul><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p>The <strong>Recent results</strong> section shows the outcome of each scheduled run:</p><ul><li><strong>Status</strong> — e.g. completed, failed.</li><li><strong>Time</strong> — when the run executed.</li><li><strong>Output</strong> — the saved outfit recommendation, or an error message if it failed.</li></ul><p>Completed recommendations are also copied to your <strong><a href="./account-and-support.html#inbox">Inbox</a></strong>. If that copy fails, the completed result remains in run history.</p><p>Runs enforce account access and the current Free recommendation allowance or Pro App Credit balance before generation, and use the same account-default AI model as Style. Demo sessions cannot save schedules.</p><h2 id="how-scheduling-works" tabindex="-1">How scheduling works <a class="header-anchor" href="#how-scheduling-works" aria-label="Permalink to &quot;How scheduling works&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Supabase Cron</p><p>The scheduler runs via <strong>Supabase Cron</strong> (not Vercel Cron) and invokes the secure worker each minute. A bounded worker claims one job per invocation, so provider latency and queued jobs can delay delivery. Daily/weekly schedules preserve local wall-clock time across daylight-saving changes. Missed occurrences are skipped after one run, not backfilled with repeated charges. Failed recurring runs advance to a future occurrence; failed one-offs are disabled instead of repeatedly calling providers.</p></div><p>See the <a href="./../development/#hosting-and-background-jobs">contributor guide</a> for background-job setup.</p>',15)])])}const g=t(r,[["render",s]]);export{h as __pageData,g as default};
